// The seller with the most settled jobs (its own record prices the premium; pools are never aggregated).
const pools = $json.pools || [];
const best = pools.filter((p) => /^0x[0-9a-fA-F]{40}$/.test(p.sellerId || '')).sort((a, b) => (b.settled || 0) - (a.settled || 0))[0];
if (!best) throw new Error('no seller with a record came back from /v1/pools');
return [{ json: { seller: best.sellerId, settled: best.settled, cheated: best.cheated, jobs: best.jobs, pool: best.vault || null, pool_chain: ($json.chain || {}).chainId || null, sellers_seen: pools.length } }];

// The action Build Call encodes. jobId: a fresh random 32 bytes (yours to choose); premium: what the quote charges.
const t = $('Job terms').first().json, q = $json, s = $('Pick a seller').first().json;
if (!q.ok || (q.refusals || []).length) throw new Error('the quote refused these terms: ' + JSON.stringify(q.refusals || q.error));
const hex = [...Array(64)].map(() => Math.floor(Math.random() * 16).toString(16)).join('');
return [{ json: { action: { kind: 'fund-job', jobId: '0x' + hex, seller: s.seller, token: t.token, price: String(t.price),
  premium: String(q.premium.chargedUnits), deposit: String(t.deposit), deadline: Math.floor(Date.now() / 1000) + 3600 * Number(t.deadline_hours) } } }];

const s = $('Pick a seller').first().json, q = $('Quote').first().json, a = $('Fund-job action').first().json.action, c = $json;
return [{ json: {
  seller: s.seller, record: q.record || null,
  premium: q.premium ? { label: q.premium.label, charged_units: q.premium.chargedUnits, basis: q.premium.basis } : null,
  terms: q.terms || null, job_id: a.jobId, chain_id: (c.calls || [])[0] ? c.calls[0].chainId : null,
  calls: (c.calls || []).map((x, i) => ({ step: i + 1, to: x.to, data: x.data, value: x.value, effect: x.effect, signer: x.signer })),
  note: c.note || null, signed_or_sent: 'nothing: hand these to the named signer, in order',
} }];
